/**
 * Measures count and enumeration with a pending removal set held in a separate native LMDB dictionary.
 *
 * <p>
 * Each removal store is offset with unrelated dictionary values, and cache clearing before each invocation makes the
 * measured traversal exercise distinct Float or Double object translations rather than warm ID caches. Run a single
 * method with JMH's {@code -prof gc} to capture normalized allocation.
 */
@State(Scope.Benchmark)
@BenchmarkMode(Mode.AverageTime)
@OutputTimeUnit(TimeUnit.MICROSECONDS)
@Warmup(iterations = 5)
@Measurement(iterations = 5)
@Fork(1)
@Threads(1)
public class LmdbNativeDeltaStatementCountBenchmark {

	private static final ValueFactory VALUE_FACTORY = SimpleValueFactory.getInstance();

	@Param({ "10000", "100000" })
	public int statementCount;

	@Param({ "FLOAT", "DOUBLE" })
	public String objectType;

	private File dataDir;
	private LmdbSailStore backingStore;
	private NativeDeltaModelFactory deltaModelFactory;
	private SnapshotSailStore snapshots;
	private SailSource removalBranch;
	private Resource subject;
	private IRI predicate;
	private Resource context;

	@Setup(Level.Trial)
	public void setUp() throws Exception {
		dataDir = Files.newTemporaryFolder();
		File backingDirectory = new File(dataDir, "backing");
		if (!backingDirectory.isDirectory() && !backingDirectory.mkdirs()) {
			throw new IOException("Could not create backing LMDB directory: " + backingDirectory);
		}
		LmdbStoreConfig config = new LmdbStoreConfig("spoc,posc").setInlineLiterals(false);
		backingStore = new LmdbSailStore(backingDirectory, new StoreProperties(backingDirectory), config);
		subject = VALUE_FACTORY.createIRI("urn:count-benchmark:shared-subject");
		predicate = VALUE_FACTORY.createIRI("urn:count-benchmark:shared-predicate");
		context = VALUE_FACTORY.createIRI("urn:count-benchmark:shared-context");
		try (SailSink sink = backingStore.getExplicitSailSource().sink(IsolationLevels.NONE)) {
			for (int i = 0; i < statementCount; i++) {
				sink.approve(subject, predicate, object(i), context);
			}
			sink.flush();
		}

		deltaModelFactory = new NativeDeltaModelFactory(new File(dataDir, "deltas"), config);
		snapshots = new SnapshotSailStore(backingStore, deltaModelFactory);
		removalBranch = snapshots.getExplicitSailSource().fork();
		try (SailSink sink = removalBranch.sink(IsolationLevels.SNAPSHOT)) {
			for (int i = 0; i < statementCount - 1; i++) {
				Statement removed = VALUE_FACTORY.createStatement(subject, predicate, object(i), context);
				sink.deprecate(removed);
			}
			sink.flush();
		}

		try (SailDataset dataset = removalBranch.dataset(IsolationLevels.SNAPSHOT)) {
			long remaining = dataset.getStatementCount(subject, predicate, null, context);
			if (remaining != 1) {
				throw new IllegalStateException("Expected one remaining statement, got " + remaining);
			}
		}
	}

	@Setup(Level.Invocation)
	public void clearDictionaryCaches() {
		((ValueStore) backingStore.getValueFactory()).clearCaches();
		deltaModelFactory.clearCaches();
	}

	@TearDown(Level.Trial)
	public void tearDown() throws Exception {
		try {
			if (removalBranch != null) {
				removalBranch.close();
			}
		} finally {
			try {
				if (snapshots != null) {
					snapshots.close();
				}
			} finally {
				try {
					if (deltaModelFactory != null) {
						deltaModelFactory.close();
					}
				} finally {
					if (dataDir != null) {
						LmdbTestUtil.deleteDir(dataDir);
					}
				}
			}
		}
	}

	@Benchmark
	public long countAfterNativeSpilledRemovals() {
		try (SailDataset dataset = removalBranch.dataset(IsolationLevels.SNAPSHOT)) {
			return dataset.getStatementCount(subject, predicate, null, context);
		}
	}

	@Benchmark
	public long enumerateAfterNativeSpilledRemovals() {
		long count = 0;
		try (SailDataset dataset = removalBranch.dataset(IsolationLevels.SNAPSHOT);
				CloseableIteration<? extends Statement> statements = dataset.getStatements(subject, predicate, null,
						context)) {
			while (statements.hasNext()) {
				statements.next();
				count++;
			}
		}
		return count;
	}

	private Literal object(int ordinal) {
		if ("FLOAT".equals(objectType)) {
			return VALUE_FACTORY.createLiteral(Float.intBitsToFloat(0x3f000000 + ordinal));
		}
		return VALUE_FACTORY.createLiteral(Double.longBitsToDouble(0x3fe0000000000000L + ordinal));
	}

	private static final class NativeDeltaModelFactory implements ModelFactory, AutoCloseable {
		private final File root;
		private final LmdbStoreConfig config;
		private final List<LmdbSailStore> stores = new ArrayList<>();

		private NativeDeltaModelFactory(File root, LmdbStoreConfig config) {
			this.root = root;
			this.config = config;
		}

		@Override
		public Model createEmptyModel() {
			File directory = new File(root, "delta-" + stores.size());
			try {
				if (!directory.isDirectory() && !directory.mkdirs()) {
					throw new IOException("Could not create delta LMDB directory: " + directory);
				}
				LmdbSailStore store = new LmdbSailStore(directory, new StoreProperties(directory), config);
				ValueStore values = (ValueStore) store.getValueFactory();
				for (int i = 0; i < 8; i++) {
					values.storeValue(VALUE_FACTORY.createLiteral("dictionary-offset:" + i));
				}
				values.commit();
				stores.add(store);
				return new SailSourceModel(store);
			} catch (IOException e) {
				throw new UncheckedIOException(e);
			}
		}

		private void clearCaches() {
			for (LmdbSailStore store : stores) {
				((ValueStore) store.getValueFactory()).clearCaches();
			}
		}

		@Override
		public void close() throws SailException {
			for (LmdbSailStore store : stores) {
				store.close();
			}
		}
	}
}
